/* @autogenerated */
import { catchError, defer, from, map, mergeMap, Observable, of, tap, throwError } from 'rxjs';
import { Acl } from '../acl/acl.model';
import {
  DownloadBlob,
  RepositoryProvider,
  Slide,
  UploadProgress,
} from '../repository/provider/repository-provider.interface';
import { matchesQuery } from './offline-ops';
import { isNetworkError, OFFLINE_FILE_PREFIX, OfflineOp } from './offline.model';
import type { OfflineQueueService } from './offline-queue.service';

/** Error de una entidad borrada sin conexión: se comporta como si ya no existiera en el servidor. */
const DELETED_OFFLINE = { status: 404, message: 'Deleted offline' };

/** Sin red y sin una lectura guardada: el error que se propaga. */
const NO_CONNECTION = new TypeError('Failed to fetch (offline)');

/**
 * Provider que envuelve al real para trabajar sin conexión (ver {@link OfflineQueueService}). Con el modo offline
 * desactivado todas las llamadas pasan al real tal cual.
 *
 * - Escrituras: sin red o con cambios pendientes se encolan; si la llamada falla por la red, también.
 * - Lecturas: las entidades con cambios pendientes se sirven desde su copia local; sin red, desde la última respuesta
 *   guardada. Los listados muestran las copias locales y, en la primera página, las altas que cumplen el filtro.
 * - Adjuntos: sin red se guardan en local con una URL `offline-file://…` que se sustituye al subirlos.
 */
export class OfflineProvider<T, F> implements RepositoryProvider<T, F> {
  acl?: (key: string | null) => Observable<Acl>;
  retrieveAll?: (keys: string[]) => Observable<T[]>;
  patchAllForQuery?: (of: string, query: F, data: any) => Observable<any>;
  deleteAllForQuery?: (query: F) => Observable<any>;

  constructor(
    private readonly queue: OfflineQueueService,
    private readonly raw: RepositoryProvider<T, F>,
    private readonly name: string,
    private readonly key: string,
    private readonly display?: string,
  ) {
    const acl = raw.acl;
    if (acl) {
      // Sin red y sin ACL guardado del elemento (p. ej. creado sin conexión) vale el genérico, el que permitió crearlo
      this.acl = (key) =>
        this.read(
          'a',
          key ?? '',
          () => acl.call(raw, key),
          key ? () => this.queue.recall(this.name, 'a', '') : undefined,
        );
    }
    const retrieveAll = raw.retrieveAll;
    if (retrieveAll) {
      this.retrieveAll = (keys) => this.retrieveMany(keys, (missing) => retrieveAll.call(raw, missing));
    }
    // Las operaciones masivas las resuelve el servidor: necesitan conexión
    if (raw.patchAllForQuery) {
      this.patchAllForQuery = raw.patchAllForQuery.bind(raw);
    }
    if (raw.deleteAllForQuery) {
      this.deleteAllForQuery = raw.deleteAllForQuery.bind(raw);
    }
  }

  list(query: F): Observable<Slide<T>> {
    if (!this.active()) {
      return this.raw.list(query);
    }
    return this.read('l', JSON.stringify(query), () => this.raw.list(query)).pipe(
      map((slide) => this.overlay(slide, query)),
    );
  }

  retrieve(key: string): Observable<T> {
    if (!this.active()) {
      return this.raw.retrieve(key);
    }
    return defer(() => {
      const shadow = this.queue.shadow(this.name, key);
      if (shadow) {
        return shadow.deleted ? throwError(() => DELETED_OFFLINE) : of(shadow.value as T);
      }
      return this.read('r', key, () => this.raw.retrieve(key));
    });
  }

  add(item: any): Observable<T> {
    if (!this.active()) {
      return this.raw.add(item);
    }
    const op = { kind: 'add', key: item?.[this.key], payload: item } as const;
    return this.write(
      () => this.raw.add(item),
      op,
      () => this.validate(item, true),
    );
  }

  update(key: string, item: any): Observable<T> {
    if (!this.active()) {
      return this.raw.update(key, item);
    }
    return this.write(
      () => this.raw.update(key, item),
      { kind: 'update', key, payload: item },
      () => this.validate(item, false),
    );
  }

  patch(key: string, data: any, path?: string): Observable<T> {
    if (!this.active()) {
      return this.raw.patch(key, data, path);
    }
    const shadow = this.queue.shadow(this.name, key)?.value;
    return this.write(
      () => this.raw.patch(key, data, path),
      { kind: 'patch', key, payload: data, path },
      // Solo se puede validar si se conoce la entidad completa
      () => (shadow && !path ? this.validate({ ...shadow, ...data }, false) : of(undefined)),
    );
  }

  delete(key: string): Observable<void> {
    if (!this.active()) {
      return this.raw.delete(key);
    }
    return this.write(
      () => this.raw.delete(key),
      { kind: 'delete', key },
      () => of(undefined),
    ).pipe(map(() => undefined));
  }

  downloadFile(endpoint: string): Observable<DownloadBlob> {
    if (!endpoint?.startsWith(OFFLINE_FILE_PREFIX)) {
      return this.raw.downloadFile(endpoint);
    }
    return from(this.queue.file(endpoint)).pipe(
      mergeMap((file) =>
        file ? of(new DownloadBlob(file.blob, file.name)) : throwError(() => new Error('offline.error.missingFile')),
      ),
    );
  }

  storeFile(endpoint: string, name: string, file: File): Observable<UploadProgress> {
    if (!this.active()) {
      return this.raw.storeFile(endpoint, name, file);
    }
    const local = () =>
      from(this.queue.storeFile(this.name, endpoint, name, file)).pipe(
        map((url) => new UploadProgress().innerData(url)),
      );
    // Un adjunto no depende de nada: con red se sube aunque haya cambios pendientes
    if (!this.queue.online()) {
      return local();
    }
    return this.raw.storeFile(endpoint, name, file).pipe(
      catchError((error) => {
        if (!isNetworkError(error)) {
          return throwError(() => error);
        }
        this.queue.markOffline();
        return local();
      }),
    );
  }

  validate(item: any, isNew: boolean): Observable<unknown> {
    return this.raw.validate ? this.raw.validate(item, isNew) : of(undefined);
  }

  private active(): boolean {
    return this.queue.enabled();
  }

  /**
   * Escribe directamente o encola. Se encola sin red o con cambios pendientes; si la escritura directa falla por la
   * red, se encola marcada como incierta (puede haber llegado al servidor). Antes de encolar se valida, para que el
   * usuario vea los errores al guardar y no al sincronizar.
   */
  private write(
    direct: () => Observable<T | void>,
    op: Pick<OfflineOp, 'kind' | 'key' | 'payload' | 'path'>,
    validate: () => Observable<unknown>,
  ): Observable<T> {
    const enqueue = (uncertain: boolean) =>
      validate().pipe(
        mergeMap(() =>
          from(
            this.queue.enqueue({
              ...op,
              repo: this.name,
              label: this.label(op.payload, op.key),
              ...(uncertain ? { uncertain } : {}),
            }),
          ),
        ),
        map((value) => value as T),
      );
    return from(this.queue.ready()).pipe(
      mergeMap(() => {
        if (this.queue.shouldQueue()) {
          return enqueue(false);
        }
        return direct().pipe(
          map((value) => value as T),
          catchError((error) => {
            if (!isNetworkError(error)) {
              return throwError(() => error);
            }
            this.queue.markOffline();
            return enqueue(op.kind === 'add');
          }),
        );
      }),
    );
  }

  /**
   * Lectura con red que se guarda; sin red (o si la red falla) se sirve la última guardada o, si no la hay, la de
   * `fallback`.
   */
  private read<V>(kind: string, id: string, fetch: () => Observable<V>, fallback?: () => Promise<any>): Observable<V> {
    const stored = (cause: unknown) =>
      from(
        this.queue.recall(this.name, kind, id).then((value) => (value === undefined && fallback ? fallback() : value)),
      ).pipe(mergeMap((value) => (value === undefined ? throwError(() => cause) : of(value as V))));
    return defer(() => {
      if (!this.queue.online()) {
        return stored(NO_CONNECTION);
      }
      return fetch().pipe(
        tap((value) => this.queue.remember(this.name, kind, id, value)),
        catchError((error) => {
          if (!isNetworkError(error)) {
            return throwError(() => error);
          }
          this.queue.markOffline();
          return stored(error);
        }),
      );
    });
  }

  /** Varios por clave: los que tienen copia local no se piden; sin red se sirven los guardados. */
  private retrieveMany(keys: string[], fetch: (missing: string[]) => Observable<T[]>): Observable<T[]> {
    if (!this.active()) {
      return fetch(keys);
    }
    return defer(() => {
      const local: T[] = [];
      const missing: string[] = [];
      keys.forEach((key) => {
        const shadow = this.queue.shadow(this.name, key);
        if (!shadow) {
          missing.push(key);
        } else if (!shadow.deleted) {
          local.push(shadow.value);
        }
      });
      if (!missing.length) {
        return of(local);
      }
      const stored = () =>
        from(Promise.all(missing.map((key) => this.queue.recall(this.name, 'r', key)))).pipe(
          map((found) => [...local, ...found.filter((item) => item !== undefined)]),
        );
      if (!this.queue.online()) {
        return stored();
      }
      return fetch(missing).pipe(
        tap((rows) => rows.forEach((row: any) => this.queue.remember(this.name, 'r', row?.[this.key], row))),
        map((rows) => [...local, ...rows]),
        catchError((error) => {
          if (!isNetworkError(error)) {
            return throwError(() => error);
          }
          this.queue.markOffline();
          return stored();
        }),
      );
    });
  }

  /** Aplica las copias locales a una página: sustituye las modificadas, quita las borradas y añade las altas. */
  private overlay(slide: Slide<T>, query: F): Slide<T> {
    if (!slide) {
      return slide;
    }
    const content: T[] = [];
    const seen = new Set<string>();
    (slide.content ?? []).forEach((item: any) => {
      const key = item?.[this.key];
      seen.add(key);
      const shadow = this.queue.shadow(this.name, key);
      if (!shadow) {
        content.push(item);
      } else if (!shadow.deleted) {
        content.push(shadow.value);
      }
    });
    // Las altas pendientes, solo en la primera página
    if (!(query as any)?.cursor) {
      this.queue
        .created(this.name)
        .filter((shadow) => !seen.has(shadow.key) && matchesQuery(shadow.value, query, this.key))
        .forEach((shadow) => content.unshift(shadow.value));
    }
    return { ...slide, content };
  }

  private label(payload: any, key: string): string {
    const value = this.display ? payload?.[this.display] : undefined;
    const fromShadow = this.display ? this.queue.shadow(this.name, key)?.value?.[this.display] : undefined;
    return String(value ?? fromShadow ?? key);
  }
}
